precision highp float;

// ================= UNIFORMS =================
// Most editors use one of these two names for the screen input.
uniform sampler2D tDiffuse;
uniform sampler2D uPreviousFrame;

uniform vec2 uResolution;
uniform float uCellSize;   // Try 15.0
uniform float uGap;        // Try 2.0
uniform float uContrast;   // Try 0.1
uniform float uIntensity;  // Try 1.0
uniform float uBaseScale;  // Try 1.2
uniform vec3 uBgColor;     // Try black: 0,0,0
uniform vec3 uFgColor;     // Try white: 1,1,1
uniform int uUseColor;     // Try 1 (Use video colors)
uniform int uMode;         // 0-15 (Animation Modes)
uniform int uShape;        // 0-20 (Shape Selectors)
uniform float uTime;       // Used for animations
uniform vec2 uMouse;       // Mouse position for ripple effect
uniform float uRippleStrength; // Strength of the ripple effect
uniform float uRippleSize; // Size of the ripple effect
uniform int uRippleShape; // Shape of the ripple effect

// --- SAFE PI DEFINITION ---
#ifndef PI
#define PI 3.14159265359
#endif

// ================= SDF PRIMITIVES (ALL SHAPES) =================
float sdCircle(vec2 p, float r) { return length(p) - r; }
float sdBox(vec2 p, vec2 b) { vec2 d = abs(p) - b; return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0); }
float sdTri(vec2 p, float r) { const float k = sqrt(3.0); p.x = abs(p.x) - r; p.y = p.y + r/k; if(p.x+k*p.y > 0.0) p = vec2(p.x-k*p.y, -k*p.x-p.y)/2.0; p.x -= clamp(p.x, -2.0*r, 0.0); return -length(p)*sign(p.y); }
float sdDiamond(vec2 p, float r) { vec2 q = p / r; q.x = abs(q.x); q.x *= 1.3; q.y = -q.y; q.y += 0.45; float d1 = dot(q, normalize(vec2(1.0, 1.2))) - 0.85; float d2 = dot(q, normalize(vec2(0.3, -1.0))) - 0.4; float d3 = q.y - 0.45; return max(d1, max(d2, d3)) * r; }
float sdHex(vec2 p, float r) { const vec3 k = vec3(-0.866025404, 0.5, 0.577350269); p = abs(p.yx); p -= 2.0*min(dot(k.xy, p), 0.0)*k.xy; p -= vec2(clamp(p.x, -k.z*r, k.z*r), r); return length(p)*sign(p.y); }
float sdOctagon(vec2 p, float r) { const vec3 k = vec3(-0.9238795325, 0.3826834323, 0.4142135623); p = abs(p); p -= 2.0*min(dot(vec2(k.x,k.y),p),0.0)*vec2(k.x,k.y); p -= 2.0*min(dot(vec2(-k.x,k.y),p),0.0)*vec2(-k.x,k.y); return length(p) - r; }
float sdStar5(vec2 p, float r, float ratio) { vec2 q = p / r; const vec2 k1 = vec2(0.809016994375, -0.587785252292); const vec2 k2 = vec2(-k1.x, k1.y); q.x = abs(q.x); q -= 2.0*max(dot(k1,q),0.0)*k1; q -= 2.0*max(dot(k2,q),0.0)*k2; q.x = abs(q.x); q.y -= 1.0; vec2 ba = ratio*vec2(-k1.y,k1.x) - vec2(0,1); float h = clamp( dot(q,ba)/dot(ba,ba), 0.0, 1.0 ); return length(q-ba*h) * sign(q.y*ba.x-q.x*ba.y) * r; }
float sdHeart(vec2 p) { p.x = abs(p.x); if(p.y+p.x>1.0) return sqrt(dot(p-vec2(0.25,0.75),p-vec2(0.25,0.75))) - sqrt(2.0)/4.0; return sqrt(min(dot(p-vec2(0.00,1.00),p-vec2(0.00,1.00)), dot(p-0.5*max(p.x+p.y,0.0),p-0.5*max(p.x+p.y,0.0)))) * sign(p.x-p.y); }
float sdFlower(vec2 p, float r) { float a = atan(p.y, p.x); float d = length(p); return d - (r + sin(a*5.0)*r*0.3); }
float sdGear(vec2 p, float r) { float a = atan(p.y, p.x); float d = length(p); return d - (r + step(0.5, sin(a*8.0))*r*0.2); }
float sdRing(vec2 p, float r, float th) { return abs(length(p) - r) - th; }
float sdTrapezoid(vec2 p, float r1, float r2, float he) { vec2 k1 = vec2(r2,he); vec2 k2 = vec2(r2-r1,2.0*he); p.x = abs(p.x); p.y -= 0.0; vec2 ca = vec2(p.x-min(p.x,(p.y<0.0)?r1:r2), abs(p.y)-he); vec2 cb = p - k1 + k2*clamp( dot(k1-p,k2)/dot(k2,k2), 0.0, 1.0 ); float s = (cb.x<0.0 && ca.y<0.0) ? -1.0 : 1.0; return s*sqrt( min(dot(ca,ca),dot(cb,cb)) ); }

float getLuma(vec3 c) { return dot(c, vec3(0.299, 0.587, 0.114)); }
mat2 rotate2d(float angle){ return mat2(cos(angle), -sin(angle), sin(angle), cos(angle)); }

// Smooth Sampling function (Using uPreviousFrame as established in debugging)
vec3 getAverageColor(vec2 uv, float cellSize, vec2 res) {
    vec2 d = (1.0 / res) * cellSize * 0.25;
    vec3 c1 = texture2D(uPreviousFrame, uv).rgb;
    vec3 c2 = texture2D(uPreviousFrame, uv + vec2(d.x, d.y)).rgb;
    vec3 c3 = texture2D(uPreviousFrame, uv + vec2(-d.x, d.y)).rgb;
    vec3 c4 = texture2D(uPreviousFrame, uv + vec2(d.x, -d.y)).rgb;
    vec3 c5 = texture2D(uPreviousFrame, uv + vec2(-d.x, -d.y)).rgb;
    return (c1 + c2 + c3 + c4 + c5) / 5.0;
}

// ================= MAIN IMAGE =================
void mainImage(const in vec4 inputColor, const in vec2 uv, out vec4 outputColor) {
    vec2 vUv = uv;
    // vUv.y = 1.0 - vUv.y; // Uncomment if image is upside down

    // Ripple effect based on mouse position
    vec2 mouseAdjustedUV = vUv;
    vec2 dist = mouseAdjustedUV - uMouse;
    float len = length(dist);
    float rippleFactor = 0.0;

    // Apply different ripple shapes based on uRippleShape
    if (uRippleShape == 0) { // Circle
        rippleFactor = sin(len * uRippleSize - uTime * 5.0);
    } else if (uRippleShape == 1) { // Box
        float d = sdBox(dist * uRippleSize, vec2(0.5));
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 2) { // Triangle
        float d = sdTri(dist * uRippleSize, 0.5);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 3) { // Diamond
        float d = sdDiamond(dist * uRippleSize, 0.5);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 4) { // Hexagon
        float d = sdHex(dist * uRippleSize, 0.5);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 5) { // Octagon
        float d = sdOctagon(dist * uRippleSize, 0.5);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 6) { // Star
        float d = sdStar5(dist * uRippleSize, 0.5, 0.5);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 7) { // Heart
        float d = sdHeart(dist * uRippleSize * 2.0);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 8) { // Flower
        float d = sdFlower(dist * uRippleSize, 0.5);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    } else if (uRippleShape == 9) { // Ring
        float d = sdRing(dist * uRippleSize, 0.5, 0.1);
        rippleFactor = sin(d * 20.0 - uTime * 5.0);
    }

    float ripple = rippleFactor * uRippleStrength / (len * 10.0 + 1.0);
    mouseAdjustedUV += normalize(dist) * ripple;

    float aspect = uResolution.x / uResolution.y;
    vec2 pixelUV = mouseAdjustedUV;
    pixelUV.x *= aspect; 
    float cellsCountY = uResolution.y / uCellSize;
    vec2 currentCellIndex = floor(pixelUV * cellsCountY);

    // VARIABLES
    float globalMinDist = 100.0; 
    float maxPriority = -1.0;    
    vec3 finalShapeColor = vec3(0.0);
    float aa = 2.0 / uCellSize;

    // 5x5 Neighbor Loop
    for(float y = -2.0; y <= 2.0; y++) {
        for(float x = -2.0; x <= 2.0; x++) {

            vec2 neighborIndex = currentCellIndex + vec2(x, y);
            vec2 neighborCenterUV = (neighborIndex + 0.5) / cellsCountY;
            neighborCenterUV.x /= aspect; 

            if(neighborCenterUV.x < 0.0 || neighborCenterUV.x > 1.0 || neighborCenterUV.y < 0.0 || neighborCenterUV.y > 1.0) continue;

            vec3 col = getAverageColor(neighborCenterUV, uCellSize, uResolution);

            // Contrast
            float contrastFactor = (1.015 * (uContrast + 1.0)) / (1.0 * (1.015 - uContrast));
            col = contrastFactor * (col - 0.5) + 0.5;
            col = clamp(col, 0.0, 1.0);

            float luma = getLuma(col);

            // --- MODES (0-15) ---
            float scaleX = uBaseScale; float scaleY = uBaseScale; float rot = 0.0; vec2 offset = vec2(0.0);

            if (uMode == 1) { scaleX = scaleY = luma * uBaseScale * 1.5; }
            else if (uMode == 2) { scaleX = scaleY = (1.0 - luma) * uBaseScale * 1.5; }
            else if (uMode == 3) { rot = luma * PI * uIntensity; }
            else if (uMode == 4) { scaleY = luma * uBaseScale * 3.0; scaleX = uBaseScale * 0.4; }
            else if (uMode == 5) { scaleX = luma * uBaseScale * 3.0; scaleY = uBaseScale * 0.4; }
            else if (uMode == 6) { if (mod(neighborIndex.x + neighborIndex.y, 2.0) < 0.5) scaleX = scaleY = luma * uBaseScale * 1.5; else scaleX = scaleY = (1.0 - luma) * uBaseScale * 1.5; }
            else if (uMode == 7) { offset.x = sin(uTime * 5.0 + neighborIndex.y * 0.5) * 0.2 * uIntensity; offset.y = cos(uTime * 3.0 + neighborIndex.x * 0.5) * 0.2 * uIntensity; }
            else if (uMode == 8) { offset.x = (luma - 0.5) * uIntensity; }
            else if (uMode == 9) { offset.y = luma * uIntensity; }
            else if (uMode == 10) { scaleX = scaleY = abs(luma - 0.5) * 2.0 * uBaseScale; }
            else if (uMode == 11) { float dist = length(neighborCenterUV - 0.5); scaleX = scaleY = (sin(dist * 20.0 - uTime * 5.0) * 0.5 + 0.5) * luma * uBaseScale * 2.0; }
            else if (uMode == 12) { float q = floor(luma * 4.0) / 4.0; scaleX = scaleY = q * uBaseScale * 1.5; }
            else if (uMode == 13) { float n = fract(sin(dot(neighborIndex, vec2(12.9898, 78.233))) * 43758.5453); scaleX = scaleY = (luma + n * 0.5) * uBaseScale; }
            else if (uMode == 14) { rot = atan(neighborIndex.y, neighborIndex.x) * uIntensity + luma; scaleX = scaleY = luma * uBaseScale; }
            else if (uMode == 15) { if (luma < 0.5) scaleX = scaleY = 0.0; else scaleX = scaleY = uBaseScale; }

            vec2 cellCenter = (neighborIndex + 0.5 + offset) / cellsCountY;
            vec2 p = pixelUV - cellCenter;
            if (rot != 0.0) p = rotate2d(rot) * p;
            p *= cellsCountY; 

            float gapFactor = 1.0 - (uGap / uCellSize);
            if (scaleX < 0.001 || scaleY < 0.001) continue;
            float effSize = 0.5 * gapFactor;
            float d = 1.0;

            // --- SHAPES (0-20) ---
            if (uShape == 0) d = sdCircle(p, effSize * scaleX); 
            else if (uShape == 1) d = sdBox(p, vec2(effSize * scaleX, effSize * scaleY));
            else if (uShape == 2) d = sdTri(p, effSize * scaleX);
            else if (uShape == 3) d = sdDiamond(p, effSize * scaleX);
            else if (uShape == 4) d = sdHex(p, effSize * scaleX);
            else if (uShape == 5) d = sdBox(p, vec2(effSize * scaleX * 0.2, effSize * scaleY)); 
            else if (uShape == 6) d = sdBox(p, vec2(effSize * scaleX, effSize * scaleY * 0.2)); 
            else if (uShape == 7) d = sdBox(rotate2d(0.785)*p, vec2(effSize * scaleX * 0.2, effSize * scaleY * 1.5));
            else if (uShape == 8) d = sdBox(rotate2d(-0.785)*p, vec2(effSize * scaleX * 0.2, effSize * scaleY * 1.5));
            else if (uShape == 9) d = sdOctagon(p, effSize * scaleX);
            else if (uShape == 10) d = sdStar5(vec2(p.x, -p.y), effSize * scaleX, 0.5);
            else if (uShape == 11) d = sdHeart(rotate2d(PI)*p / (effSize * scaleX * 1.5));
            else if (uShape == 12) d = sdFlower(p, effSize * scaleX * 0.8);
            else if (uShape == 13) d = sdGear(p, effSize * scaleX * 0.8);
            else if (uShape == 14) d = sdRing(p, effSize * scaleX, effSize * scaleX * 0.2);
            else if (uShape == 15) d = max(sdBox(p, vec2(effSize*scaleX)), -sdBox(p, vec2(effSize*scaleX*0.8)));
            else if (uShape == 16) d = sdTrapezoid(p, effSize*scaleX*0.5, effSize*scaleX, effSize*scaleY);
            else if (uShape == 17) d = sdBox(rotate2d(0.785)*p, vec2(effSize*scaleX, effSize*scaleY));
            else if (uShape == 18) d = min(sdBox(p, vec2(effSize*scaleX*0.2, effSize*scaleY)), sdBox(p, vec2(effSize*scaleX, effSize*scaleY*0.2)));
            else if (uShape == 19) { vec2 pc = p; pc.y += effSize*scaleY*0.5; d = abs(sdTri(pc, effSize*scaleX)) - effSize*scaleX*0.2; }
            else if (uShape == 20) { float a = atan(p.y, p.x); float mouth = step(0.5, sin(a + uTime*10.0)); d = sdCircle(p, effSize * scaleX); if (p.x > 0.0 && abs(p.y) < p.x * 0.5) d = 1.0; }

            globalMinDist = min(globalMinDist, d);

            if (d < aa) {
                if (luma > maxPriority) {
                    maxPriority = luma;
                    finalShapeColor = (uUseColor == 1) ? col : uFgColor;
                }
            }
        }
    }

    float mask = 1.0 - smoothstep(0.0, aa, globalMinDist);
    vec3 result = mix(uBgColor, finalShapeColor, mask);
    outputColor = vec4(result, 1.0);
}
